// === Tab: mySketch ===
let balls = [];
let clicking = false;

function setup() {
	createCanvas(windowWidth, windowHeight);

	for (let i = 0; i < 200; i++) {
		balls.push(new Ball(random(width), random(height), 10));
	}
}

function draw() {
	background(30);

	for (let ball of balls) {
		ball.move();
		ball.checkWalls();
	}

	for (let i = 0; i < balls.length; i++) {
		for (let j = i + 1; j < balls.length; j++) {
			balls[i].collideWith(balls[j]);
		}
	}

	for (let ball of balls) {
		ball.show();
	}

	if (clicking) {
		fill(0)
		circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 100)
	}
}

function mousePressed() {
	clicking = true;
}

function mouseReleased() {
	clicking = false;
}

class Ball {
	constructor(x, y, r) {
		this.pos = createVector(x, y);
		this.vel = p5.Vector.random2D().mult(1.2);
		this.r = r;
	}

	move() {
		this.pos.add(this.vel);
		this.vel.y += 0.1;
	}

	checkWalls() {
		if (this.pos.x - this.r < 0) {
			this.vel.x *= -0.9;
			this.pos.x = this.r;
		}

		if (this.pos.x + this.r > width) {
			this.vel.x *= -0.9;
			this.pos.x = width - this.r;
		}

		if (this.pos.y - this.r < 0) {
			this.vel.y *= -0.9;
			this.pos.y = this.r;
		}

		if (this.pos.y + this.r > height) {
			this.vel.y *= -0.9;
			this.pos.y = height - this.r;
		}

		if (this.pos.y - this.r < (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + 50 & this.pos.y + this.r > (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - 50 & this.pos.x - this.r < (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + 50 & this.pos.x + this.r > (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - 50 & clicking) {
			this.vel.y += (this.pos.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) / 10;
			this.vel.x += (this.pos.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / 10;
		}
	}

	collideWith(other) {
		let distance = dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y);
		let minDistance = this.r + other.r;

		if (distance < minDistance) {
			let overlap = minDistance - distance;
			let direction = p5.Vector.sub(this.pos, other.pos).normalize();

			this.pos.add(direction.copy().mult(overlap / 2));
			other.pos.sub(direction.copy().mult(overlap / 2));

			let temp = this.vel.copy();
			this.vel = other.vel.copy();
			this.vel.x *= 0.9;
			this.vel.y *= 0.9;
			other.vel = temp;
		}
	}

	show() {
		colorMode(HSB);
		fill((abs(this.vel.x + this.vel.y) / 10) * 360, 100, 100);
		colorMode(RGB);
		noStroke();
		circle(this.pos.x, this.pos.y, this.r * 2);
	}
}

